graphSearchArguments.gql:
MATCH (p:`Project`)-[:`usesTechnology`]->(t:`Technology`)
WHERE EXISTS { (p)-[:`deliveredBy`]->(d:`Organization` WHERE d.name = 'Kestrel Consulting') }
  AND EXISTS { (p)-[:`deliveredFor`]->(c:`Organization` WHERE c.name = 'Mediva Care Group') }
  AND t.name = 'Databricks'
RETURN DISTINCT p.name AS project_name, t.name AS technology_name
